for (let y = 0; y < H; y++) {
    const ratio = y / H;
    const color = `rgb(${Math.floor(20 + ratio * 15)}, ${Math.floor(10 + ratio * 10)}, ${Math.floor(30 + ratio * 15)})`;
    ctx.fillStyle = color;
    ctx.fillRect(0, y, W, 1);
}

// Draw spiral
const centerX = W / 2;
const centerY = H / 2;
const maxRadius = Math.min(W, H) / 2 - 20;

function drawSpiral(radius, angle, depth) {
    if (depth > 0) {
        const x = centerX + Math.cos(angle) * radius;
        const y = centerY + Math.sin(angle) * radius;

        // Draw segment
        ctx.fillStyle = ACCENT;
        ctx.globalAlpha = 0.7 - depth * 0.1;
        ctx.beginPath();
        ctx.moveTo(centerX, centerY);
        ctx.lineTo(x, y);
        ctx.strokeStyle = ACCENT;
        ctx.lineWidth = 2;
        ctx.lineCap = 'round';
        ctx.stroke();

        // Recursive calls for next segment
        const nextRadius = radius * 1.1;
        const nextAngle = angle + 0.3;
        drawSpiral(nextRadius, nextAngle, depth - 1);
    }
}

